const mt05_live_field_t mt05_live_fields[] = {
    { 0x0, 2, "Unsigned", "VAFCMULT", "Airflow Correction Factor", "$Val/32768", "", 3, "Airflow Correction Factor" },
    { 0x2, 2, "Unsigned", "AFFNLAFR", "Air-Fuel Ratio Measured", "$Val/2048", "", 2, "Input from the fuel trims, oxygen sensor etc. The ECU tries to match the Air-Fuel Ratio Target. This value should be near to Air-Fuel Ratio Target. The perfect stoichiometric air-fuel ratio (AFR) is 14.7:1" },
    { 0x4, 2, "Unsigned", "AFTAFR", "Air-Fuel Ratio Target", "$Val/2048", "", 2, "Pre programmed Air Fuel Ratio for the condition (Target AFR) The perfect stoichiometric air-fuel ratio (AFR) is 14.7:1" },
    { 0x6, 2, "Unsigned", "FBLMCOR1", "LTFT Corr Factor Cyl 1", "$Val/32768", "", 3, "Long Term Fuel Trim Correction Factor (BLM = Block Learn Multiplier) Ideal value is 1. Eg 1.1 = more fuel, 0.9 = less fuel. Documentation says this parameter should be in the range 0.75 to 1.15 for idle speed. Depending on the O2 sensor, the short term adaption increases (>0) or decreases (<0) the amount of fuel from the calibration values to get the optimal air/fuel mix. If the short term adaption deviates too much, the long term adaption will be adapted and stored in the flash memory of the ECU. The BLM may compensate e.g. a worn fuel pump or a clogged fuel injector." },
    { 0x8, 2, "Unsigned", "FBLMCOR2", "LTFT Corr Factor Cyl 2", "$Val/32768", "", 3, "Long Term Fuel Trim Correction Factor (BLM = Block Learn Multiplier) Ideal value is 1. Eg 1.1 = more fuel, 0.9 = less fuel. Documentation says this parameter should be in the range 0.75 to 1.15 for idle speed. Depending on the O2 sensor, the short term adaption increases (>0) or decreases (<0) the amount of fuel to the calibration values to get the optimal air/fuel mix. If the short term adaption deviates too much, the long term adaption will be adapted and stored in the flash memory of the ECU. The BLM may compensate e.g. a worn fuel pump or a clogged fuel injector." },
    { 0xa, 2, "Signed", "FCATCYL1", "Charge Air Temp Cyl 1", "$Val/128", "°C", 1, "Charge air temperature for cylinder 1. The estimated temperature of the air/fuel mix entering the cylinder. Calculated from Inlet Air Temperature and Engine (coolant) Temperature and other parameters." },
    { 0xc, 2, "Signed", "FCATCYL2", "Charge Air Temp Cyl 2", "$Val/128", "°C", 1, "Charge air temperature for cylinder 2. The estimated temperature of the air/fuel mix entering the cylinder. Calculated from Inlet Air Temperature and Engine (coolant) Temperature and other parameters." },
    { 0xe, 2, "Signed", "FCLCINT1", "Short Term Corr Int Cyl 1", "", "", 0, "Short term adaption integral learned while in closed loop. Documentation says this parameter should be in the range -15 to +15 for idle speed. Depending on the O2 sensor, the short term adaption increases (>0) or decreases (<0) the amount of fuel to the calibration values to get the correct air/fuel mix. If the short term adaption deviates too much, the long term adaption will be adapted and stored in the flash memory of the ECU. See https://en.wikipedia.org/wiki/PID_controller" },
    { 0x10, 2, "Signed", "FCLCINT2", "Short Term Corr Int Cyl 2", "", "", 0, "Short term adaption integral learned while in closed loop. Documentation says this parameter should be in the range -15 to +15 for idle speed. Depending on the O2 sensor, the short term adaption increases (>0) or decreases (<0) the amount of fuel from the calibration values to get the correct air/fuel mix. If the short term adaption deviates too much, the long term adaption will be adapted and stored in the flash memory of the ECU. See https://en.wikipedia.org/wiki/PID_controller" },
    { 0x12, 2, "Signed", "FCLCMUL1", "Short Term Corr Add Cyl 1", "$Val/1024", "%", 2, "Closed loop fuel correction addition. The ECU may add fuel to (>0) or subtract from (<0) the default amount." },
    { 0x14, 2, "Signed", "FCLCMUL2", "Short Term Corr Add Cyl 2", "$Val/1024", "%", 2, "Closed loop fuel correction addition. The ECU may add fuel to (>0) or subtract from (<0) the default amount." },
    { 0x16, 2, "Unsigned", "FCNO", "Long Term BLM Cell", "", "", 0, "BLM (Block Learn Multiplier) Cell (0-35): Long term fuel trim cell used in the stored table. The 'LTFT Corr Factor' is read from this cell in the BLM table. See help --> appendix for more details" },
    { 0x18, 2, "Unsigned", "FPPDC", "Fuel Pump Duty Cycle", "$Val/327.68", "%", 0, "Defines the speed with which the fuel pump motor is running." },
    { 0x1a, 2, "Unsigned", "FPWVC1", "Injector Time Cyl 1", "$Val/64", "ms", 2, "Length of time that fuel is injected in milliseconds (longer = more fuel) Documentation says this parameter should be in the range 1.5 ms to 2.6 ms for idle speed and up to 6 ms for higher speed." },
    { 0x1c, 2, "Unsigned", "FPWVC2", "Injector Time Cyl 2", "$Val/64", "ms", 2, "Length of time that fuel is injected in milliseconds (longer = more fuel) Documentation says this parameter should be in the range 1.5 ms to 2.6 ms for idle speed and up to 6 ms for higher speed." },
    { 0x1e, 2, "Unsigned", "FVE1", "Volume Efficiency Cyl 1", "$Val/327.68", "%", 1, "Describes the amount of fuel/air in the cylinder in relation to regular atmospheric air. If the cylinder is filled with fuel/air at atmospheric pressure, then the engine is said to have 100% volumetric efficiency. Normally aspirated engines typically run anywhere between 80% and 100% VE. The value comes from the calibration tables in the ECU." },
    { 0x20, 2, "Unsigned", "FVE2", "Volume Efficiency Cyl 2", "$Val/327.68", "%", 1, "Describes the amount of fuel/air in the cylinder in relation to regular atmospheric air. If the cylinder is filled with fuel/air at atmospheric pressure, then the engine is said to have 100% volumetric efficiency. Normally aspirated engines typically run anywhere between 80% and 100% VE. The value comes from the calibration tables in the ECU." },
    { 0x22, 1, "Unsigned", "IACVDSMP", "IACV Position Target", "", "", 0, "Idle Air Control Valve (stepper motor) desired pintle position, controls the amount of air that enters the engine while the throttle is released. IMPORTANT: Any problem with cranking/idle speed: Read the appendix about the IACV in the help file." },
    { 0x23, 2, "Unsigned", "IAINTEGOFST", "IACV Integral", "$Val/327.68", "%", 2, "Airflow integral offset of Idle Air Control Valve, learned during IAC closed loop mode. See https://en.wikipedia.org/wiki/PID_controller" },
    { 0x25, 2, "Unsigned", "IARDRPM", "Idle Speed Target", "$Val/4", "rpm", 0, "Pre-programed desired idle engine speed" },
    { 0x27, 2, "Unsigned", "IARPMERR", "Idle Speed Error", "$Val/4", "rpm", 0, "Speed deviation from Idle Speed Target" },
    { 0x29, 2, "FaultCurr", "MALFCURR", "Current Fault Code", "", "", 0, "Current malfunction code. It turns the EFI/MIL indicator on. A current DTC cannot be cleared as long as the fault is still present." },
    { 0x2b, 2, "FaultHist", "MALFHIST", "Historic Fault Code", "", "", 0, "Old stored malfunction code from previous engine runs. A historic DTC stays until it is cleared or the fault did not appear anymore during multiple driving cycles. It does not turn on the EFI/MIL indicator." },
    { 0x2d, 2, "Time", "RUNTIME", "Engine Runtime", "", "", 0, "The time which the motor is running" },
    { 0x2f, 2, "Signed", "SAESTA", "Spark Adv Measured", "$Val/128", "°CA", 1, "The ECU tries to match the Spark Advance Target. Measured in Crank Angle = degrees Before Top Dead Center (BTDC)" },
    { 0x31, 2, "Signed", "SAGLOBAL1", "Spark Adv Target", "$Val/128", "°CA", 1, "Pre-programed spark advance for the condition (desired spark advance). Measured in Crank Angle = degrees Before Top Dead Center (BTDC) Positive values: Spark plugs are fired before the piston is at top dead center. Negative values: Spark plugs are fired after the piston has passed over top dead center. The spark angle varies considerably with engine speed, load and temperature. Typical values for idle speed are between 8 and 15 degrees." },
    { 0x33, 2, "Signed", "SAIDLDYN", "Dynam. Idle Spark Adv", "$Val/128", "°CA", 1, "Dynamically advance or retard the spark at idle speed to get a smooth operation." },
    { 0x35, 2, "Unsigned", "SPDWELL", "Spark Dwell Time", "$Val/64", "ms", 2, "The time the spark coil is charged with energy (longer = stronger spark) The ECU calculates this based on battery voltage and speed." },
    { 0x37, 1, "BitFlags", "", "", "", "", 0, "" },
    { 0x38, 1, "BitFlags", "", "", "", "", 0, "" },
    { 0x39, 1, "BitFlags", "", "", "", "", 0, "" },
    { 0x3a, 1, "BitFlags", "", "", "", "", 0, "" },
    { 0x3b, 1, "BitFlags", "", "", "", "", 0, "" },
    { 0x3c, 1, "Unsigned", "TERRCNT", "CKP Sensor Errors", "", "", 0, "The Crankshaft Position Error counter indicates how many times the crankshaft position could not be determined correctly since the engine has been started. This should remain zero otherwise backfire may be the consequence. The crankshaft sensor at the flywheel gives one pulse every 15 degree. There are 24 positions, but one tooth is missing, so there are 23 pulses per rotation. This way the ECU knows always the exact position of the crankshaft. When the number of teeth counted for one revolution of the crankshaft is not 23, this 'Loss of Sync Counter' is incremented by 1. When the number of lost sync counts gets high enough a failure code will be signaled. The reason may be an incorrect CKP sensor gap, a damaged cable shield or the spark pulses radiate into the CKP sensor signal due to wrong spark plugs or too close cables." },
    { 0x3d, 1, "Unsigned", "VAFCCLNUM", "Airflow Correction Cell", "", "", 0, "This indicates which cell of the stored table is being used." },
    { 0x3e, 2, "Signed", "VAFRRAW1", "Vehicle Speed", "$Val > 0 ? ($Val/128) : 0", "km/h", 0, "This parameter may be used if a vehicle speed sensor exists." },
    { 0x40, 2, "Unsigned", "VAFRRAW2", "Carbon Canister Purge", "$Val/327.68", "%", 0, "Some motorbikes have an evaporative emission reduction system: A charcoal filled canister absorbs fuel vapor from the fuel tank and when the engine is running the fuel in the carbon canister is purged via a valve back into the engine intake manifold. The ECU regulates the flux of the ECP (Evaporative Canister Purge) by controlling the duty cycle of the valve's voltage. See Delphi MT05 manual page 51. In the Benelli TRK 251 logile you see this parameter in action." },
    { 0x42, 2, "Unsigned", "VBARO", "MAP Baro Pressure", "$Val/256", "kPa", 1, "Manifold Air Pressure / Temperature sensor: Atmosheric Pressure (Average sea-level pressure is 101 kPa)" },
    { 0x44, 2, "Signed", "VCLTS", "Coolant Temperature", "$Val/128", "°C", 1, "Cylinder Temperature (from Engine Head Temperature (EHT) sensor) or Coolant Temperature (from Engine Coolant Temperature (ECT) sensor)" },
    { 0x46, 2, "Unsigned", "VCSFC", "MAP CID Fail Counter", "", "", 0, "Manifold Air Pressure / Temperature sensor Cylinder Identification (CID) failed. Cylinder Inlet Stroke not detected counter. This should remain at zero." },
    { 0x48, 2, "Unsigned", "VCSPC", "MAP CID Pass Counter", "", "", 0, "Manifold Air Pressure / Temperature sensor Cylinder Identification (CID) success. Cylinder Inlet Stroke successfully detected counter" },
    { 0x4a, 2, "Signed", "VIAT", "Inlet Air Temperature", "$Val/128", "°C", 1, "Manifold Air Pressure / Temperature sensor: Intake Air Temperature" },
    { 0x4c, 2, "Unsigned", "VIGN", "Ignition Voltage", "$Val/2048", "V", 1, "This is equivalent to the battery voltage but measured behind the ignition switch and the kill switch. The voltage should be between 12V and 12.8V when the motor is off. It should increase to 14V - 15V when the motor is running. Otherwise check the battery, generator and rectifier. The consumption of lights and ventilator decreases the voltage. If starting the motor (cranking) decreases the voltage to less than 8V the battery is empty or at end of life. The Delphi MT05 needs at least 6.3V to operate correctly." },
    { 0x4e, 2, "Unsigned", "VMAP", "MAP Intake Pressure", "$Val/256", "kPa", 1, "Manifold Air Pressure / Temperature sensor: Intake pressure (partial vacuum e.g idle 40 kpa, full load near 100 kpa) This pressure is a measure of the load on the engine." },
    { 0x50, 2, "Unsigned", "VMAPALTC", "MAP Altitude Compens", "$Val/256", "kPa", 1, "Manifold Air Pressure / Temperature sensor: Altitude compensated MAP reading" },
    { 0x52, 2, "Unsigned", "VMAPEXP", "Expected Inlet Pressure", "$Val/256", "kPa", 1, "Expected manifold inlet air pressure calculated from MAP sensor values" },
    { 0x54, 2, "Unsigned", "VMAPRANG", "MAP Read Angle", "$Val/64", "°CA", 0, "The crankshaft angle at which the MAP sensor is read once per engine cycle. Measured in Crank Angle = degrees Before Top Dead Center (BTDC). To get a measurement representative of load. It must be measured at the minimum value associated with the propagating vacuum pulse." },
    { 0x56, 2, "Unsigned", "VO2", "O2 Sensor Voltage Cyl 1", "$Val/64", "mV", 0, "The current voltage from the O2 (lambda) sensor. (high = rich = no oxygen in exhaust, low = lean = oxygen present) Initially high while sensor is heating up. When the engine is running properly in Closed Loop, the O2 voltage should always be oscillating between 100 mV and 900 mV." },
    { 0x58, 2, "Unsigned", "VRPM", "Engine Speed", "$Val/4", "rpm", 0, "The current speed of the engine" },
    { 0x5a, 2, "Unsigned", "VTHROT", "Throttle Position", "$Val/327.68", "%", 1, "The throttle position from 0% (fully released) to 100% (Wide Open Throttle) is calculated from the TPS sensor voltage. With the throttle self-learning the ECU learns which voltage corresponds to 0% and which voltage corresponds to 100%" },
    { 0x5c, 2, "Unsigned", "VTHROTIA", "TPS Compens with IACV", "$Val/327.68", "%", 1, "Throttle Position Sensor value with Idle Air Control Valve Position compensation" },
    { 0x5e, 2, "Unsigned", "VTHROTRAW", "TPS Sensor Voltage", "$Val/13107", "V", 3, "Voltage from Throttle Position Sensor (between 0V and 5V)" },
    { 0x60, 2, "Time", "PRUNTIME", "Previous Engine Runtime", "", "", 0, "The time which the motor was running the last time before turning the ignition off." },
    { 0x62, 2, "Unsigned", "VO2B", "O2 Sensor Voltage Cyl 2", "$Val/64", "mV", 0, "The current voltage from the O2 (lambda) sensor. (high = rich = no oxygen in exhaust, low = lean = oxygen present) Initially high while sensor is heating up. When the engine is running properly in Closed Loop, the O2 voltage should always be oscillating between 100 mV and 900 mV." },
    { 0xff, 0, "Calculated", "ALTITUDE", "Altitude", "CalcAltitude($VBARO, $VIAT)", "m", 0, "The altitude above sea level is calculated from the Atmospheric Pressure and the Intake Air Temperature." },
    { 0x0, 4, "Unsigned", "PRODUCT1", "Harware Part Number", "", "", 0, "Delphi part number (printed on the label on the ECU)" },
    { 0x0, 4, "Unsigned", "PRODUCT2", "Software Part Number", "", "", 0, "Delphi Software Number" },
    { 0x0, 4, "Unsigned", "IGNCOUNT", "Ignition Counter", "", "", 0, "Counts how often the ignition key has been turned on. To increment this counter the ignition key has to be turned off for at least 10 seconds before turning it on again." },
    { 0x0, 8, "Ascii", "CALIBVER", "Calibration Version", "", "", 0, "The version number of the calibration table area in the ECU flash memory" },
    { 0xff, 0, "DtcCodes", "DTC_VENDOR", "DTC_VENDOR", "", "", 0, "" },
};
