const mt05_live_bit_t mt05_live_bits[] = {
    { 0x37, 0, "B_FUELCOFF", "Fuel Cut Off Enable", "Fuel cut off means that the ECU stops injecting fuel for a short moment. This may happen because the throttle has been released (deceleration) or to limit the engine speed.", "", "diag_flag_c9f0" },
    { 0x37, 1, "B_FCOCRFLD", "Clear Flood Enable", "", "", "diag_flag_c91c" },
    { 0x37, 2, "B_DFCOCMET", "DFCO Met", "Deceleration Fuel Cut Off Criteria Met", "", "diag_flag_c92e" },
    { 0x37, 3, "B_DFCOENBL", "DFCO Enter", "Deceleration Fuel Cut Off Enter", "", "diag_flag_ca44" },
    { 0x37, 4, "B_DFCOEENBL", "DFCO Exit", "Deceleration Fuel Cut Off Exit", "", "diag_flag_c89e" },
    { 0x37, 5, "B_FCOHRPM", "Speed Limiter", "Over speed fuel cut off is currently active", "", "engine_state == 3" },
    { 0x37, 6, "B_VRLVENBL", "Roll Over Enabled", "This shows the status of pin J1-14 of the ECU (low active). On some motorbikes this is connected to the roll-over switch which switches this pin to ground when the motorbike has fallen down in an accident so the engine is turned off (Interlock Fuel Cut Off). The meaning of this pin is defined in the calibration 'J1-14 Input Usage'. Study also the diagram of your vehicle to see to what pin 14 of the grey ECU plug is connected.", "", "DAT_e00894" },
    { 0x37, 7, "B_FCLREST2", "C/L Reset Cyl 2", "Closed Loop Adaption Reset. ECU resets short term trim to zero.", "", "diag_flag_caf9" },
    { 0x38, 0, "B_FCLCEN1", "C/L Enabled Cyl 1", "Closed Loop correction enabled. The O2 sensor monitors the exhaust gas to regulate the air/fuel mixture delivered to the engine. When the engine is under high load, the Closed Loop must be deactivated to allow the air/fuel mixture to be rich.", "", "diag_flag_c92b" },
    { 0x38, 1, "B_PPDSEBL", "Prime Pulse Disable", "The ECU injects a small amount of fuel when the ignition is turned on. No more fuel is injected until the engine is cranking. Prime pulse should be disabled when engine is running.", "", "diag_flag_c934" },
    { 0x38, 2, "B_FPENABL", "Fuel Pump On", "Gasoline engine: The fuel pump is running to create the pressure for the fuel injectors. Propane engine: The fuel lockout valve is enabled.", "", "DAT_e0081a" },
    { 0x38, 3, "B_FTRNSAES", "Acc Enrich Enter", "Acceleration Enrichment (rich mixture) has started. Indicates that extra fuel is being injected because the throttle has been opened quickly. Helps to eliminate hesitation in the acceleration. When the throttle is opened acceleration enrichment should be on for a short time and then return to off and stay off while the throttle is not beeing moved.", "", "diag_flag_c81c" },
    { 0x38, 4, "B_FTRNSDES", "Dec Enlean Enter", "Deceleration Enleanment or fuel cut-off mode has started. This is enabled during periods of deceleration. In this mode, the ECU reduces injector pulse width or momentarily shuts the injector off in order to reduce high emissions and engine backfire.", "", "diag_flag_c77e" },
    { 0x38, 5, "B_FTRNSAEDCLOAD", "Acc Enrich Exit", "Acceleration Enrichment state has been turned off for decreased load", "", "ram_var_c604" },
    { 0x38, 6, "B_FTRNSDEINLOAD", "Dec Enlean Exit", "Deceleration Enleanment state has been turned off for increased load", "", "diag_flag_c603" },
    { 0x38, 7, "B_FCLCEN2", "C/L Enabled Cyl 2", "Closed Loop correction enabled. O2 sensor monitors the exhaust gas to regulate the air/fuel mixture delivered to the engine. When the engine is under high load, the Closed Loop must be deactivated to allow the air/fuel mixture to be rich.", "", "DAT_e0083e == 1" },
    { 0x39, 0, "B_FO2STAT1", "O2 Sensor Rich Cyl 1", "This is the digitalized value of the O2 sensor voltage. It is on if the O2 sensor voltage is above 500 mV and off if below 500 mV. Rich Engine: Little or no oxygen in exhaust, more fuel than there is oxygen to burn it. Lean Engine: Oxygen present in exhaust, excess oxygen left over after burning the fuel.", "", "diag_flag_c784" },
    { 0x39, 1, "B_FCLREST1", "C/L Reset Cyl 1", "Closed Loop Adaption Reset. ECU resets short term trim to zero.", "", "diag_flag_c850" },
    { 0x39, 2, "B_FOSHTREN", "O2 Sensor Heater Enable", "O2 sensor heating element enabled. This helps to bring the O2 sensor sensor up to operating temperature more quickly. The sensor must be at least 350 °C in order to function.", "", "diag_flag_c786" },
    { 0x39, 3, "B_FO2REDY1", "O2 Sensor Ready Cyl 1", "O2 sensor has reached operating temperature. (Closed loop is only possible once this has happened)", "", "diag_flag_c780" },
    { 0x39, 4, "B_IACVMODE0", "IACV Correction on", "Idle Air Control Valve (stepper motor) closed loop correction enabled. If this flag is OFF although running idle for a longer time the ECU has lost control over the idle speed due to a defect.", "", "diag_flag_c781" },
    { 0x39, 5, "B_IAMTRLOST", "IACV Lost Step", "Idle Air Control Valve (stepper motor) lost step. This may happen under low battery condition, resulting in step count loss.", "", "diag_flag_c78d" },
    { 0x39, 6, "B_IACMVIHB", "IACV Move Inhibit", "Idle Air Control Valve (stepper motor) move inhibit. Indicates that the IAV is blocked.", "", "DAT_e00844" },
    { 0x39, 7, "B_VIGNS", "Ignition On", "The ignition key is turned on", "", "diag_flag_cac6" },
    { 0x3a, 0, "B_CYCSENBL", "MAP CID Enable", "Manifold Absolute Pressure Sensor Cylinder Identificatin (CID) Enable. When the intake valve suddenly opens, the manifold pressure (MAP) sensor detects a sharp pressure drop (about 1 kPa). This allows to detect the position of the cylinder.", "", "diag_flag_cad0 == 1" },
    { 0x3a, 1, "B_VCSINSYN", "MAP CID Succeed", "Manifold Absolute Pressure Sensor Cylinder Identificatin (CID) Success", "", "diag_flag_cac5" },
    { 0x3a, 2, "B_IDLCONM", "Idle Mode", "Engine is idle. This means the engine is running and the throttle position is zero.", "", "DAT_e00810" },
    { 0x3a, 3, "B_FPESTAT", "Power Enrichment Enable", "Applied when putting a continuous load on the engine (more fuel in the Air/Fuel mix)", "", "diag_flag_caf8" },
    { 0x3a, 4, "B_FPEAFREN", "PE Protection Enable", "Power Enrichment Air Fuel Ratio Protection Enabled. Makes sure that the air/fuel ratio never becomes too lean when the engine is under load which may cause damage.", "", "DAT_e0089e" },
    { 0x3a, 5, "B_PNSWITCH", "Clutch / Neutral Switch", "This shows the status of pin J1-18 of the ECU (low active). This pin is mostly switched to ground when the clutch is pulled or the neutral gear is active. It may also be used as reverse gear input on ATV's or for testing overspeed fuel cutoff. The meaning of this pin is defined in the calibration 'J1-18 Input Usage'. Study also the diagram of your vehicle to see to what pin 18 of the grey ECU plug is connected.", "", "DAT_e0085c" },
    { 0x3a, 6, "B_DIAGSWTCH", "Diagnostic Mode", "This shows the status of pin J1-16 of the ECU (low active) which enables Diagnostic Mode. The meaning of this pin is defined in the calibration 'J1-16 Input Usage'. Read the help file for more details.", "", "DAT_e00846" },
    { 0x3a, 7, "B_MILSTATUS", "MIL Fault Light on", "The Malfunction Indicator Light ('MIL') shows that a fault is present.", "", "diag_flag_c954" },
    { 0x3b, 0, "B_VAFCMET", "Airflow Correction Met", "Inlet Pressure Correction on. The ECU makes corrections between actual atmospheric pressure and the sea level atmospheric pressure (101 kPa) ??", "", "diag_flag_cad6" },
    { 0x3b, 1, "B_VBAROCMET", "Baro Update Met", "Atmospheric pressure updates enabled", "", "diag_flag_c014" },
    { 0x3b, 2, "B_VCSINSYNSPRK", "Seq. Spark Enable", "Sequential Spark Mode. Opposite of wasted spark. Uses the MAP CID to know the correct moment when to create the spark. The advantage of sequential ignition is at idle and low speed. It will provide cleaner emissions and smoother idle. Over about 2500 RPM there is no advantage.", "", "diag_flag_c824" },
    { 0x3b, 3, "B_SATITRIG", "Spark Tip-In Enable", "Tip-In Spark Advance Retard Trigger. Tip-In = Throttle is opened quickly", "", "diag_flag_c841" },
    { 0x3b, 4, "B_CATLOENB", "Cat Light Off Enable", "Catalyst Light-off logic enabled", "", "diag_flag_c830" },
    { 0x3b, 5, "B_ENGSTATE3", "Engine Running", "The engine is running", "", "diag_flag_c836" },
    { 0x3b, 6, "B_NISTBLIDLE", "Stable Warm Idle", "The ECU is satisfied that all factors have met their requirement for a stable effecient idle. One factor is the coolant temperature which needs to reach 60 to 70 °C.", "", "diag_flag_c840" },
    { 0x3b, 7, "B_FO2REDY2", "O2 Sensor Ready Cyl 2", "O2 sensor has reached operating temperature. (Closed loop is only possible once this has happened)", "", "diag_flag_cad7" },
};
